chain-of-responsibility-pattern.pseudocode:
class Handler:
    def __init__(self, limit, nxt=None):
        self.limit = limit
        self.next = nxt  # 다음 처리자 (사슬)
    def handle(self, amount):
        if amount <= self.limit:  # 처리 가능 → 직접 처리
            return f'{self.name()} 승인'
        if self.next is not None:  # 불가 → 다음으로 전달
            return self.next.handle(amount)
        return '미처리'  # 사슬 끝까지 처리자 없음

class TeamLead(Handler):
    def name(self): return '팀장'
class Director(Handler):
    def name(self): return '부장'
class CEO(Handler):
    def name(self): return '사장'

chain = TeamLead(100, Director(1000, CEO(10000)))
chain.handle(500)  # → '부장 승인' (클라이언트는 첫 처리자만 앎)

challenge-response-authentication.pseudocode:
def issue_challenge(session):
    session.nonce = random_bytes(16)  # 일회성 난수
    session.expires = now() + 60
    return session.nonce

def respond(key, nonce):  # 증명자 측
    return hmac_sha256(key, nonce)

def verify(session, key, response):
    if session.nonce is None or now() > session.expires:
        return False  # 만료·재사용 차단
    expected = hmac_sha256(key, session.nonce)
    session.nonce = None  # 한 번 쓰고 폐기
    return constant_time_eq(expected, response)

checkpoint.pseudocode:
def restart(log):
    cp = log.last_checkpoint()
    undo = set(cp.active_list)  # 체크포인트 시점 활성 L
    redo = set()
    for r in log.records_after(cp):  # 순방향 분석
        if r.kind == 'start':
            undo.add(r.tx)
        elif r.kind == 'commit':
            undo.discard(r.tx)
            redo.add(r.tx)
    # 역방향 UNDO: 미완료 트랜잭션 갱신 취소
    for r in log.backward():
        if not undo:
            break
        if r.tx in undo and r.kind == 'update':
            write(r.item, r.old_value)
        elif r.tx in undo and r.kind == 'start':
            undo.discard(r.tx)  # 시작점까지 취소 완료
    # 순방향 REDO: 체크포인트 이후 커밋분만
    for r in log.records_after(cp):
        if r.tx in redo and r.kind == 'update':
            write(r.item, r.new_value)

checkpoint-restart.pseudocode:
def run_with_checkpoint(work, state, store, interval):
    i = state.get('step', 0)  # 재시작 시 이어받음
    while i < work.total:
        work.do_step(i, state)
        i += 1
        if i % interval == 0:  # 주기적 저장
            state['step'] = i
            store.save(state)  # 비휘발성 저장
    return state

def restart(work, store, interval):
    # 저장된 상태 복원, 없으면 초기 상태
    state = store.load() or {'step': 0}
    return run_with_checkpoint(work, state, store, interval)

chord.pseudocode:
def between(x, a, b, incl_right=False):  # 원형 구간
    if a < b:
        return a < x < b or (incl_right and x == b)
    return x > a or x < b or (incl_right and x == b)

def find_successor(n, key):
    # key가 (n, successor] 안이면 successor가 담당
    if between(key, n.id, n.successor.id, True):
        return n.successor
    p = closest_preceding_node(n, key)
    return find_successor(p, key)  # 원격 호출

def closest_preceding_node(n, key):
    for f in reversed(n.finger):  # 먼 핑거부터
        if between(f.id, n.id, key):  # (n, key) 안
            return f
    return n

chunking.pseudocode:
def chunk_fixed(tokens, size=500, overlap=50):
    # 고정 크기 + 오버랩: 경계에서 잘린 맥락을 이어 줌
    step = size - overlap
    chunks = []
    for start in range(0, len(tokens), step):
        chunks.append(tokens[start:start + size])
        if start + size >= len(tokens):
            break  # 마지막 청크
    return chunks

def with_metadata(chunks, doc_id):
    # 검색 결과의 출처 표시·필터링용 메타데이터 부착
    return [{'doc': doc_id, 'seq': i, 'text': c}
            for i, c in enumerate(chunks)]

