churn-prediction.pseudocode:
def churn_score(model, customer):
    x = features(customer)  # 이용·거래·불만 피처
    p = model.predict_proba(x)  # 이탈 확률 0~1
    return p

def target_retention(customers, model, threshold):
    targets = []
    for c in customers:
        if churn_score(model, c) >= threshold:
            targets.append(c)  # 고위험 고객 선정
    return targets  # 방어 캠페인 대상
